{
  "function": {
    "name": "COMPOSIO_MANAGE_CONNECTIONS",
    "description": "\nCreate or manage connections to user's apps. Returns a branded authentication link that works for OAuth, API keys, and all other auth types.\n\nCall policy:\n- First call COMPOSIO_SEARCH_TOOLS for the user's query.\n- If COMPOSIO_SEARCH_TOOLS indicates there is no active connection for a toolkit, call COMPOSIO_MANAGE_CONNECTIONS with the exact toolkit name(s) returned.\n- Do not call COMPOSIO_MANAGE_CONNECTIONS if COMPOSIO_SEARCH_TOOLS returns no main tools and no related tools.\n- Toolkit names in toolkits must exactly match toolkit identifiers returned by COMPOSIO_SEARCH_TOOLS; never invent names.\n- NEVER execute any toolkit tool without an ACTIVE connection.\n\nTool Behavior:\n- If a connection is Active, the tool returns the connection details. Always use this to verify connection status and fetch metadata.\n- If a connection is not Active, returns a authentication link (redirect_url) to create new connection.\n- If reinitiate_all is true, the tool forces reconnections for all toolkits, even if they already have active connections.\n\nWorkflow after initiating connection:\n- Always show the returned redirect_url as a FORMATTED MARKDOWN LINK to the user, and ask them to click on the link to finish authentication.\n- Begin executing tools only after the connection for that toolkit is confirmed Active.\n    ",
    "parameters": {
      "properties": {
        "toolkits": {
          "description": "List of toolkits to check or connect. Should be a valid toolkit returned by SEARCH_TOOLS (never invent one). If a toolkit is not connected, will initiate connection. Example: ['gmail', 'exa', 'github', 'outlook', 'reddit', 'googlesheets', 'one_drive']. This parameter is required.",
          "items": {
            "properties": {},
            "type": "string"
          },
          "title": "Toolkits",
          "type": "array"
        },
        "reinitiate_all": {
          "default": false,
          "description": "Force reconnection for ALL toolkits in the toolkits list, even if they already have Active connections.\n              WHEN TO USE:\n              - You suspect existing connections are stale or broken.\n              - You want to refresh all connections with new credentials or settings.\n              - You're troubleshooting connection issues across multiple toolkits.\n              BEHAVIOR:\n              - Overrides any existing active connections for all specified toolkits and initiates new link-based authentication flows.\n              DEFAULT: false (preserve existing active connections). Please provide a value of type boolean.",
          "title": "Reinitiate All",
          "type": "boolean"
        },
        "session_id": {
          "description": "ALWAYS pass the session_id that was provided in the SEARCH_TOOLS response. Please provide a value of type string.",
          "title": "Session ID",
          "type": "string"
        }
      },
      "required": [
        "toolkits"
      ],
      "title": "ManageConnectionsRequest",
      "type": "object"
    },
    "strict": null
  },
  "type": "function"
}
